        if ($match === null) return null;
        $inserido = str_replace('$ufs = [', '', $newEol);
        return substr_replace($codigo, $inserido, $match[1], 0);
    }
    if (str_contains($antigo, 'continuar_questionario')) {
        if (!str_contains($codigo, 'name="continuar_questionario"') && !str_contains($codigo, "name='continuar_questionario'")) {
            // Alterações anteriores já removeram o controle antigo; o formulário novo abaixo substitui esse fluxo.
            return $codigo;
