        // O checkbox antigo deve ser removido sem afetar os outros campos de perfil.
        $regex = '~<div\\b(?=[^>]*\\bclass\\s*=\\s*["\'][^"\']*\\bform-check\\b[^"\']*["\'])[^>]*>\\s*<input\\b(?=[^>]*\\bname\\s*=\\s*["\']continuar_questionario["\'])[^>]*>.*?</label>\\s*<div\\b[^>]*\\bclass\\s*=\\s*["\'][^"\']*\\bform-text\\b[^"\']*["\'][^>]*>.*?</div>\\s*</div>~is';
