        return substr_replace($codigo, trim($newEol), $match[1], strlen($match[0]));
    }
    if (str_contains($antigo, 'justify-content-end gap-2 mb-5')) {
        if (str_contains($codigo, 'id="questionarioCompletoAdmin"')) return $codigo;
        $insert = str_replace($antigo, '', $newEol);
        if ($insert === $newEol) return null;
        $regex = '~<div\\b[^>]*class\\s*=\\s*["\'][^"\']*\\bd-flex\\b[^"\']*\\bjustify-content-end\\b[^"\']*\\bmb-5\\b[^"\']*["\'][^>]*>~i';
        $match = $acharUnico($regex, $codigo);
        if ($match !== null) return substr_replace($codigo, $insert, $match[1], 0);
